require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/auth.php';require_login();require_module_access($conn, 'laboratory', 'edit');require_role(['admin','lab']);
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$csrf=$_SESSION['csrf_token'];$id=(int)($_GET['id']??0);$item=$conn->query("SELECT * FROM lab_inventory WHERE id=".$id)->fetch_assoc();if(!$item)exit('Item not found.');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf_token']??'')))$error='Invalid security token.';else{$type=$_POST['movement_type']??'';$qty=(float)($_POST['quantity']??0);if(!in_array($type,['in','out','adjustment'],true)||$qty<=0)$error='Invalid movement.';else{$conn->begin_transaction();try{$s=$conn->prepare("SELECT quantity FROM lab_inventory WHERE id=? FOR UPDATE");$s->bind_param('i',$id);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();$current=(float)$r['quantity'];$new=$type==='in'?$current+$qty:($type==='out'?$current-$qty:$qty);if($new<0)throw new Exception('Insufficient stock.');$u=$conn->prepare("UPDATE lab_inventory SET quantity=? WHERE id=?");$u->bind_param('di',$new,$id);$u->execute();$u->close();$uid=(int)($_SESSION['user_id']??0);$note=trim($_POST['note']??'');$m=$conn->prepare("INSERT INTO lab_inventory_movements(inventory_id,movement_type,quantity,balance_after,note,user_id) VALUES(?,?,?,?,?,?)");$m->bind_param('isddsi',$id,$type,$qty,$new,$note,$uid);$m->execute();$m->close();$conn->commit();header('Location: stock_movements.php?id='.$id);exit;}catch(Throwable $e){$conn->rollback();$error=$e->getMessage();}}}}
$rows=$conn->query("SELECT * FROM lab_inventory_movements WHERE inventory_id=".$id." ORDER BY id DESC");
