<div class="container-fluid"><h2><?=htmlspecialchars($item['item_name'])?> — Stock Movements</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="card shadow mb-4"><div class="card-body"><form method="post" class="row"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><div class="col-md-3"><select name="movement_type" class="form-control"><option value="in">Stock In</option><option value="out">Stock Out</option><option value="adjustment">Set Balance</option></select></div><div class="col-md-3"><input name="quantity" type="number" step="0.01" min="0.01" class="form-control" placeholder="Quantity" required></div><div class="col-md-4"><input name="note" class="form-control" placeholder="Reason / reference"></div><div class="col-md-2"><button class="btn btn-success">Save</button></div></form></div></div><div class="card shadow"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Date</th><th>Type</th><th>Qty</th><th>Balance</th><th>Note</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['created_at']?></td><td><?=strtoupper($r['movement_type'])?></td><td><?=number_format($r['quantity'],2)?></td><td><?=number_format($r['balance_after'],2)?></td><td><?=htmlspecialchars($r['note']??'')?></td></tr><?php endwhile;?></tbody></table></div></div></div>
